(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-967":{scenario:{company:"Solvenna Power Trading",supervisor:{name:"Mạc Thị Hồng Nhung",role:{vi:"Trưởng bộ phận Giao dịch & Quyết toán điện",en:"Head of Power Trading & Settlement"}},ref_code:"ST-1026",title:{vi:"Đúng giá tham chiếu. Đúng tiền quyết toán.",en:"Right reference price. Right settlement."},brief:{vi:"Bạn lập bảng quyết toán hợp đồng sai khác (CfD) tháng 10, hồ sơ ST-1026, giữa nhà máy điện gió của công ty và một khách hàng mua điện trực tiếp (DPPA) qua lưới quốc gia. Giá hợp đồng 1850 đ/kWh; sản lượng hợp đồng tính thanh toán 3000000 kWh; SMP bình quân gia quyền 1286 đ/kWh, CAN 197 đ/kWh. Hợp đồng quy định giá tham chiếu là giá thị trường toàn phần. Sửa giá tham chiếu và tiền quyết toán (triệu đồng) trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"You are preparing the October contract for difference (CfD) settlement, file ST-1026, between the company's wind farm and a direct power purchase (DPPA) customer via the national grid. Strike price 1850 VND/kWh; contracted settlement volume 3000000 kWh; volume-weighted SMP 1286 VND/kWh, CAN 197 VND/kWh. The contract sets the full market price as the reference. Correct the reference price and the settlement amount (million VND) in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Hợp đồng CfD & dữ liệu giá đã xác nhận · ST-1026",en:"CfD contract & confirmed price data · ST-1026"},fields:[{id:"REF_PRICE",label:{vi:"Giá tham chiếu CfD",en:"CfD reference price"},initial:"SMP",expected:"FMP",choices:["SMP","FMP","CAN"],reference:"Điều khoản quyết toán hợp đồng",hint:{vi:"Giá thị trường toàn phần gồm cả giá điện năng thị trường và giá công suất thị trường của từng chu kỳ.",en:"The full market price combines the market energy price and the market capacity price of each period."}},{id:"CFD_MVND",label:{vi:"Tiền quyết toán CfD (triệu đồng)",en:"CfD settlement (million VND)"},initial:"1692",expected:"1101",reference:"Bảng quyết toán tháng 10",ref_value:{vi:"Giá hợp đồng 1850; SMP 1286; CAN 197 (đ/kWh); sản lượng 3000000 kWh",en:"Strike 1850; SMP 1286; CAN 197 (VND/kWh); volume 3000000 kWh"},hint:{vi:"Lấy giá hợp đồng trừ giá tham chiếu đúng điều khoản, nhân với sản lượng hợp đồng rồi đổi sang triệu đồng.",en:"Subtract the contractual reference price from the strike, multiply by contracted volume and convert to million VND."}}],sop32:{vi:"Tiền quyết toán CfD = (giá hợp đồng - giá tham chiếu) x sản lượng hợp đồng; giá tham chiếu FMP = SMP + CAN bình quân gia quyền theo sản lượng; kết quả dương thì bên mua trả cho bên bán.",en:"CfD settlement = (strike price - reference price) x contracted volume; reference FMP = SMP + CAN, volume-weighted; a positive result means the buyer pays the seller."},context:{label:"ETRM / ST-1026",metrics:[{label:{vi:"Giá hợp đồng",en:"Strike price"},value:"1,850 VND/kWh"},{label:{vi:"SMP bình quân gia quyền",en:"Volume-weighted SMP"},value:"1,286 VND/kWh"},{label:{vi:"Giá công suất CAN",en:"Capacity price CAN"},value:"197 VND/kWh"},{label:{vi:"Sản lượng hợp đồng",en:"Contracted volume"},value:"3,000,000 kWh"}]},crisis:{vi:"Giám đốc thương mại nhắn: “Cứ xuất hóa đơn theo SMP như bản nháp, khách hàng chưa chắc đã đối chiếu, khoản chênh gần 600 triệu là lợi nhuận quý này. Nếu họ hỏi thì bảo lỗi hệ thống.”",en:"The commercial director messages you: “Invoice on SMP as in the draft, the customer may never reconcile it and the gap of almost 600 million is this quarter's profit. If they ask, call it a system error.”"},options:{safe:{vi:"Quyết toán theo FMP đúng hợp đồng, báo giám đốc tài chính và pháp chế bằng văn bản; rà soát các kỳ trước và thông báo minh bạch cho khách hàng nếu đã tính sai.",en:"Settle on FMP per the contract, inform the CFO and legal in writing; review earlier periods and notify the customer transparently if they were miscalculated."},shortcut:{vi:"Xuất hóa đơn theo SMP, chỉ điều chỉnh khi khách hàng phát hiện và khiếu nại.",en:"Invoice on SMP and only adjust if the customer notices and complains."},wait:{vi:"Treo bảng quyết toán, chờ giám đốc thương mại và khách hàng tự thương lượng.",en:"Hold the settlement and wait for the commercial director and the customer to negotiate."}},questions:{vi:["Vì sao giá tham chiếu phải là FMP chứ không phải SMP? Dữ liệu nào cho ra số tiền quyết toán đã sửa?","Nếu các tháng trước đã quyết toán theo SMP, bạn xử lý rủi ro hợp đồng và quan hệ khách hàng như thế nào?"],en:["Why must the reference be FMP rather than SMP? Which data produces the corrected settlement amount?","If earlier months were settled on SMP, how do you handle the contractual risk and the customer relationship?"]},hints:{vi:["Đọc kỹ điều khoản định nghĩa giá tham chiếu trong hợp đồng trước khi chọn chuỗi giá.","Cộng đủ các thành phần của giá tham chiếu rồi mới lấy chênh lệch theo SOP mục 3.2.","Đọc lại SOP mục 4.2: quyết toán phải đúng hợp đồng; mọi chỉ đạo xuất hóa đơn sai phải được báo cáo."],en:["Read the contract clause defining the reference price before choosing the price series.","Add every component of the reference price before taking the difference in SOP 3.2.","Re-read SOP 4.2: settlement must follow the contract; any instruction to misbill must be escalated."]}},learning:{summary:{vi:"Chuyên viên phân tích thị trường điện theo dõi giá thị trường bán buôn, dự báo phụ tải và giá, xây dựng chiến lược chào giá, quản lý danh mục hợp đồng (PPA, DPPA, CfD) và quyết toán. Nghề tạo ra quyết định mua bán điện có căn cứ, kiểm soát rủi ro giá và sản lượng, đòi hỏi kỹ năng định lượng, hiểu quy định thị trường và liêm chính tuyệt đối.",en:"An electricity market analyst tracks wholesale prices, forecasts load and prices, builds bidding strategies, manages contract portfolios (PPA, DPPA, CfD) and settlement. The role produces well-founded trading decisions and controls price and volume risk, requiring quantitative skills, knowledge of market rules and absolute integrity."},responsibilities:{vi:["Dự báo phụ tải, thủy văn, giá nhiên liệu và giá thị trường theo chu kỳ giao dịch.","Xây dựng chiến lược chào giá và lịch huy động tối ưu cho danh mục nhà máy.","Định giá, đàm phán và theo dõi hợp đồng PPA, DPPA, CfD và hợp đồng phòng ngừa rủi ro.","Lập và đối chiếu bảng quyết toán với dữ liệu giá, sản lượng đã xác nhận.","Báo cáo vị thế rủi ro, lãi lỗ và tuân thủ quy tắc liêm chính thị trường."],en:["Forecast load, hydrology, fuel prices and market prices for each trading period.","Build bidding strategies and optimal dispatch schedules for the plant portfolio.","Price, negotiate and monitor PPA, DPPA, CfD and hedging contracts.","Prepare and reconcile settlement statements against confirmed price and volume data.","Report risk positions, profit and loss and compliance with market integrity rules."]},competencies:[{name:{vi:"Phân tích định lượng",en:"Quantitative analysis"},desc:{vi:"Dùng thống kê, chuỗi thời gian và mô hình kịch bản để dự báo giá và sản lượng.",en:"Use statistics, time series and scenario models to forecast prices and volumes."}},{name:{vi:"Hiểu luật chơi thị trường",en:"Market rules"},desc:{vi:"Nắm cơ chế hình thành SMP, CAN, FMP, quy trình chào giá và quyết toán.",en:"Understand how SMP, CAN and FMP are formed, bidding procedures and settlement."}},{name:{vi:"Quản trị rủi ro",en:"Risk management"},desc:{vi:"Đo và phòng ngừa rủi ro giá, rủi ro sản lượng, rủi ro hình dạng phụ tải và đối tác.",en:"Measure and hedge price, volume, shape and counterparty risk."}},{name:{vi:"Pháp lý hợp đồng",en:"Contract literacy"},desc:{vi:"Đọc chính xác điều khoản giá tham chiếu, sản lượng, phạt và giải quyết tranh chấp.",en:"Read reference price, volume, penalty and dispute clauses precisely."}},{name:{vi:"Liêm chính thị trường",en:"Market integrity"},desc:{vi:"Từ chối thông đồng, thao túng giá chào và quyết toán sai; báo cáo bộ phận tuân thủ.",en:"Refuse collusion, bid manipulation and misbilling; escalate to compliance."}}],knowledge:{vi:["Luật Điện lực số 61/2024/QH15 và các quy định hướng dẫn về thị trường điện cạnh tranh.","Thị trường bán buôn điện cạnh tranh Việt Nam: chu kỳ giao dịch, SMP, CAN và FMP = SMP + CAN.","Cơ chế mua bán điện trực tiếp (DPPA) qua lưới quốc gia và hợp đồng sai khác theo quy định hiện hành.","Điều độ kinh tế theo thứ tự chi phí biên (merit order) và ảnh hưởng của thủy văn, nhiên liệu.","Quy tắc liêm chính thị trường: cấm thông đồng, thao túng giá chào và lạm dụng thông tin nội bộ."],en:["Electricity Law No. 61/2024/QH15 and guidance on the competitive electricity market.","Vietnam's competitive wholesale market: trading periods, SMP, CAN and FMP = SMP + CAN.","Direct power purchase (DPPA) via the national grid and contracts for difference under current rules.","Economic dispatch by marginal cost (merit order) and the impact of hydrology and fuel.","Market integrity rules: no collusion, bid manipulation or misuse of inside information."]},tools:["Hệ thống quản lý giao dịch năng lượng (ETRM)","Dữ liệu giá thị trường theo chu kỳ","Python hoặc R cho dự báo","Mô hình điều độ kinh tế","Bảng tính quyết toán","Công cụ trực quan hóa dữ liệu (BI)"],kpis:{vi:["Sai số dự báo giá và phụ tải (MAPE) theo tuần.","Tỷ lệ bảng quyết toán đúng ngay lần đầu, không phải điều chỉnh.","Lãi lỗ danh mục so với ngân sách trong giới hạn rủi ro được duyệt.","Số vi phạm quy tắc thị trường và tuân thủ (mục tiêu bằng 0)."],en:["Weekly price and load forecast error (MAPE).","Right-first-time settlement statements with no adjustments.","Portfolio profit and loss versus budget within approved risk limits.","Market rule and compliance breaches (target zero)."]},day:[{time:"07:30",vi:"Đọc kết quả thị trường ngày hôm trước, giá SMP, CAN và các sự kiện nghẽn mạch.",en:"Review yesterday's market results, SMP, CAN and congestion events."},{time:"09:00",vi:"Cập nhật dự báo phụ tải, thủy văn và giá nhiên liệu cho ngày tới.",en:"Update load, hydrology and fuel price forecasts for the day ahead."},{time:"11:00",vi:"Đề xuất bản chào giá và trình trưởng bộ phận phê duyệt trước giờ đóng cửa.",en:"Propose the bid and get approval from the head of trading before gate closure."},{time:"14:00",vi:"Đối chiếu sản lượng, giá và lập bảng quyết toán hợp đồng với khách hàng.",en:"Reconcile volumes and prices and prepare customer contract settlements."},{time:"16:30",vi:"Báo cáo vị thế rủi ro, lãi lỗ và các điểm cần chú ý cho ngày mai.",en:"Report risk positions, profit and loss and watch points for tomorrow."}],mistakes:{vi:["Dùng SMP thay cho FMP khi hợp đồng quy định giá tham chiếu là giá thị trường toàn phần.","Lấy giá bình quân số học thay vì bình quân gia quyền theo sản lượng khi quyết toán.","Nhầm chiều thanh toán của CfD, dẫn tới xuất hóa đơn ngược bên."],en:["Using SMP instead of FMP when the contract defines the full market price as reference.","Using a simple average instead of a volume-weighted average in settlement.","Getting the CfD payment direction wrong and invoicing the wrong party."]},career:[{vi:"Chuyên viên dữ liệu thị trường điện",en:"Power market data analyst"},{vi:"Chuyên viên phân tích thị trường và giao dịch điện",en:"Electricity market and trading analyst"},{vi:"Trưởng nhóm giao dịch và quản trị rủi ro",en:"Trading and risk management lead"},{vi:"Giám đốc thương mại năng lượng",en:"Head of energy commercial"}],glossary:[{term:"SMP",vi:"Giá điện năng thị trường của từng chu kỳ giao dịch, xác định theo giá chào biên.",en:"System marginal price for each trading period, set by the marginal bid."},{term:"CAN",vi:"Giá công suất thị trường, bù chi phí cố định cho nhà máy mới tốt nhất.",en:"Market capacity price that covers fixed costs of the best new entrant plant."},{term:"FMP",vi:"Giá thị trường toàn phần, bằng tổng SMP và CAN của chu kỳ giao dịch.",en:"Full market price, the sum of SMP and CAN for a trading period."},{term:"CfD",vi:"Hợp đồng sai khác: hai bên thanh toán phần chênh giữa giá hợp đồng và giá tham chiếu.",en:"Contract for difference: parties settle the gap between the strike and reference prices."},{term:"DPPA",vi:"Cơ chế mua bán điện trực tiếp giữa đơn vị phát điện tái tạo và khách hàng sử dụng điện lớn.",en:"Direct power purchase between a renewable generator and a large electricity user."}],quiz:[{q:{vi:"SMP của chu kỳ là 1200 đ/kWh, CAN là 250 đ/kWh. FMP bằng bao nhiêu?",en:"A period has SMP 1200 VND/kWh and CAN 250 VND/kWh. What is the FMP?"},options:{vi:["950 đ/kWh","1200 đ/kWh","1450 đ/kWh","1725 đ/kWh"],en:["950 VND/kWh","1200 VND/kWh","1450 VND/kWh","1725 VND/kWh"]},answer:2,explain:{vi:"FMP = SMP + CAN = 1200 + 250 = 1450 đ/kWh.",en:"FMP = SMP + CAN = 1200 + 250 = 1450 VND/kWh."}},{q:{vi:"CfD giá hợp đồng 1700 đ/kWh, FMP 1500 đ/kWh, sản lượng 2000000 kWh. Kết quả quyết toán là gì?",en:"CfD strike 1700 VND/kWh, FMP 1500 VND/kWh, volume 2000000 kWh. What is the settlement?"},options:{vi:["Bên mua trả bên bán 400 triệu đồng","Bên bán trả bên mua 400 triệu đồng","Bên mua trả bên bán 3400 triệu đồng","Không phát sinh thanh toán"],en:["Buyer pays seller 400 million VND","Seller pays buyer 400 million VND","Buyer pays seller 3400 million VND","No payment"]},answer:0,explain:{vi:"(1700 - 1500) x 2000000 = 400 triệu đồng; giá hợp đồng cao hơn giá tham chiếu nên bên mua trả bên bán.",en:"(1700 - 1500) x 2000000 = 400 million VND; the strike is above the reference, so the buyer pays the seller."}},{q:{vi:"Một nhà máy khác gợi ý hai bên “phối hợp” giá chào ngày mai. Bạn làm gì?",en:"Another plant suggests both sides “coordinate” tomorrow's bids. What do you do?"},options:{vi:["Đồng ý nếu chỉ một lần","Trao đổi qua điện thoại cá nhân","Chỉ chia sẻ giá chào cũ","Từ chối, lưu bằng chứng và báo bộ phận tuân thủ"],en:["Agree if it is only once","Discuss it on a personal phone","Share only past bids","Refuse, keep evidence and report to compliance"]},answer:3,explain:{vi:"Thông đồng giá chào là hành vi thao túng thị trường bị cấm; phải từ chối và báo cáo.",en:"Bid coordination is prohibited market manipulation; refuse and report it."}},{q:{vi:"Rủi ro hình dạng (shape risk) trong hợp đồng điện là gì?",en:"What is shape risk in a power contract?"},options:{vi:["Rủi ro đối tác mất khả năng thanh toán","Rủi ro biểu đồ sản lượng thực tế lệch với biểu đồ giá theo giờ","Rủi ro thay đổi tỷ giá","Rủi ro hư hỏng thiết bị"],en:["Counterparty default risk","Risk that the actual output profile mismatches the hourly price profile","Exchange rate risk","Equipment failure risk"]},answer:1,explain:{vi:"Sản lượng tái tạo thường cao vào giờ giá thấp, làm giá thu được bình quân thấp hơn giá thị trường bình quân.",en:"Renewable output is often high when prices are low, so the captured price falls below the average market price."}}],tools_en:["Energy trading and risk management (ETRM)","Interval market price data","Python or R for forecasting","Economic dispatch model","Settlement spreadsheet","Data visualization tool (BI)"]}}})})(window.KKR);
